def gen(rng):
    def fmt(needed, free, prereq):
        lines = [str(len(needed)), ' '.join(needed), str(len(free)), ' '.join(free)]
        for p in prereq:
            lines.append(' '.join([str(len(p))] + p))
        return '\n'.join(lines)
    tests = [
        fmt(['pandas', 'numpy'], ['a', 'b', 'c'], [['a', 'b'], ['b']]),
        fmt(['x'], ['y'], [[]]),
        fmt(['x'], ['y'], [['x']]),
        fmt(['x'], ['y'], [['z']]),
        fmt(['a', 'b'], ['f'], [['b'], ['a']]),
        fmt(['a', 'b', 'c'], ['f'], [['b'], ['c'], ['f']]),
    ]
    for m in (2, 3, 4, 6, 8, 12):
        for mode in (0, 1, 2):
            for _ in range(2):
                k = rng.randint(1, 4)
                needed = ['n%d' % i for i in range(m)]
                free = ['f%d' % i for i in range(k)]
                unknown = ['u0', 'u1']
                prereq = []
                for i in range(m):
                    if mode == 0:
                        pool = free + needed[:i]
                    elif mode == 1:
                        pool = free + needed
                    else:
                        pool = free + needed + unknown
                    c = rng.randint(0, 3)
                    prereq.append(rng.sample(pool, min(c, len(pool))))
                tests.append(fmt(needed, free, prereq))
    M = 50000
    needed = ['n%d' % i for i in range(M)]
    free = ['f%d' % i for i in range(M)]
    # long chain listed in the worst order: n_i needs n_{i+1}
    prereq = [[needed[i + 1], rng.choice(free)] for i in range(M - 1)] + [[free[0], free[1]]]
    tests.append(fmt(needed, free, prereq))
    # same chain broken in the middle by an unknown library
    prereq2 = [list(p) for p in prereq]
    prereq2[M // 2] = [needed[M // 2 + 1], 'unk']
    tests.append(fmt(needed, free, prereq2))
    # random dependencies, cycles likely
    prereq3 = []
    for i in range(M):
        pool_pick = []
        for _ in range(2):
            if rng.random() < 0.5:
                pool_pick.append(rng.choice(free))
            else:
                pool_pick.append(needed[rng.randint(0, M - 1)])
        prereq3.append(list(dict.fromkeys(pool_pick)))
    tests.append(fmt(needed, free, prereq3))
    # random DAG: needed i depends on earlier or later chain neighbours, plus one big ring
    ring = 1000
    prereq4 = []
    for i in range(M):
        if i < ring:
            prereq4.append([needed[(i + 1) % ring]])
        else:
            a = needed[rng.randint(0, i - 1)]
            b = rng.choice(free)
            prereq4.append(list(dict.fromkeys([a, b])))
    tests.append(fmt(needed, free, prereq4))
    return tests

